cd /tmp/dtd-test2 && cat > bot.mjs <<'EOF'
import { chromium } from "playwright-core";
const url = process.argv[2];
const b = await chromium.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: true });
const p = await b.newPage({ viewport: { width: 1280, height: 720 } });
const errs = []; p.on("pageerror", (e) => errs.push(e.message));
await p.goto(url);
const results = {};
for (const mode of ["easy", "normal", "hard"]) {
  results[mode] = await p.evaluate((mode) => {
    const g = window.__game; g.newGame(mode);
    // plan: serpentine vertical walls, then fill around
    const plan = [];
    const cols = [3, 7, 11, 15, 19, 23];
    cols.forEach((x, j) => {
      const ys = []; for (let y = 1; y <= 17; y += 2) ys.push(y);
      const keep = j % 2 ? ys.filter((y) => y >= 5) : ys.filter((y) => y <= 15);
      for (const y of keep) plan.push([x, y]);
    });
    for (let x = 1; x <= 24; x += 2) for (let y = 1; y <= 17; y += 2) plan.push([x, y]);
    const typeFor = (i) => (i < 8 ? 0 : [0, 1, 2, 4, 3, 0, 1, 5][i % 8]);
    let pi = 0, placedN = 0;
    const log = [];
    g.sendWave();
    let lastWave = 0;
    while (!g.state.over) {
      const s = g.state;
      // spend
      for (let guard = 0; guard < 40; guard++) {
        while (pi < plan.length && g.placeCheck(plan[pi][0], plan[pi][1]) !== "ok" && g.placeCheck(plan[pi][0], plan[pi][1]) !== "creep") pi++;
        const t = typeFor(placedN);
        const cost = [5, 15, 25, 30, 20, 40][t];
        const upg = s.towers.filter((tw) => tw.level < 4).sort((a, b) => a.spent - b.spent)[0];
        const upCost = upg ? [[5,10,20,40],[15,30,60,120],[25,50,100,200],[30,60,120,240],[20,40,80,160],[40,80,160,320]][upg.type][upg.level] : Infinity;
        const wantBuild = pi < plan.length && (placedN < 30 + s.wave * 1.2 || upCost > cost * 4);
        if (wantBuild && s.gold >= cost) {
          g.setBuild(t); const n = s.towers.length; g.tryPlace(plan[pi][0], plan[pi][1]);
          if (s.towers.length > n) placedN++; else pi++;
        } else if (s.gold >= upCost) g.upgrade(upg);
        else break;
      }
      g.setBuild(-1);
      g.step(1);
      if (s.wave !== lastWave && s.wave % 10 === 0) { log.push([s.wave, s.lives, s.towers.length, s.gold]); lastWave = s.wave; }
    }
    const s = g.state;
    return { won: s.won, wave: s.wave, lives: s.lives, towers: s.towers.length, score: s.score, log };
  }, mode);
}
console.log(JSON.stringify({ results, errs }, null, 1));
await b.close();
EOF
